vi.mock('@/api/interface.js', () => ({ inf: { auth: { groupLogin: { call: vi.fn() } } } }))
vi.mock('@/api/auth', () => ({ refreshAccessToken: vi.fn() }))

const {
	formatYmd,
	formatNumber,
	isSuccess,
	toTagArray,
	stripHtmlTags,
	parseUtcToKstDate,
	parseIsoFlexibleDate,
	formatUseDate,
	mapItemByColumns,
