	isPreviewablXlsx,
	encodeBase64,
	decodeBase64,
	makeTimestampedFileName,
	parseStoredFileName,
} = await import('@/utils/common.js')

describe('formatYmd', () => {
	it('빈 값이면 빈 문자열을 반환한다', () => {
		expect(formatYmd('')).toBe('')
		expect(formatYmd(null)).toBe('')
		expect(formatYmd(undefined)).toBe('')
	})

	it('파싱할 수 없는 값이면 빈 문자열을 반환한다', () => {
		expect(formatYmd('날짜아님')).toBe('')
	})

	it('flag 에 따라 시/분/초를 붙여 반환한다', () => {
		const d = new Date(2026, 0, 5, 9, 8, 7)
		expect(formatYmd(d)).toBe('2026-01-05')
		expect(formatYmd(d, 'hhmm')).toBe('2026-01-05 09:08')
		expect(formatYmd(d, 'hhmmss')).toBe('2026-01-05 09:08:07')
	})
})

describe('formatNumber', () => {
	it('null/undefined 는 빈 문자열을 반환한다', () => {
		expect(formatNumber(null)).toBe('')
		expect(formatNumber(undefined)).toBe('')
	})

	it('천 단위 콤마를 붙인다', () => {
		expect(formatNumber(0)).toBe('0')
		expect(formatNumber(1234)).toBe('1,234')
		expect(formatNumber('1234567')).toBe('1,234,567')
	})

	it('소수부에는 콤마를 붙이지 않는다', () => {
		expect(formatNumber(1234.5678)).toBe('1,234.5678')
	})
})

describe('isSuccess', () => {
	it('응답이 없으면 false', () => {
		expect(isSuccess(null)).toBe(false)
		expect(isSuccess({})).toBe(false)
	})

	it('success 가 boolean 이면 그 값을 그대로 사용한다', () => {
		expect(isSuccess({ data: { success: true } })).toBe(true)
		expect(isSuccess({ data: { success: false, code: 200 } })).toBe(false)
	})

	it('code 가 200 이면 성공으로 판단한다', () => {
		expect(isSuccess({ data: { code: 200 } })).toBe(true)
		expect(isSuccess({ data: { code: '200' } })).toBe(true)
		expect(isSuccess({ data: { code: 500 } })).toBe(false)
	})
})

describe('toTagArray', () => {
	it('빈 값은 빈 배열', () => {
		expect(toTagArray(null)).toEqual([])
		expect(toTagArray('')).toEqual([])
	})

	it('배열은 그대로 반환한다', () => {
		const arr = ['a', 'b']
		expect(toTagArray(arr)).toBe(arr)
	})

	it('콤마/파이프 구분 문자열을 배열로 만든다', () => {
		expect(toTagArray('a, b|c ,,')).toEqual(['a', 'b', 'c'])
	})
})

describe('stripHtmlTags', () => {
	it('문자열이 아니면 빈 문자열', () => {
		expect(stripHtmlTags(null)).toBe('')
		expect(stripHtmlTags(123)).toBe('')
